:\"visible_lines\";i:0;s:14:\"read_more_text\";s:26:\"Read more about the School\";s:13:\"read_more_url\";s:1:\"#\";s:13:\"details_table\";a:2:{i:0;a:2:{s:5:\"label\";s:8:\"Location\";s:5:\"value\";s:21:\"IIT Campus, Kharagpur\";}i:1;a:2:{s:5:\"label\";s:11:\"Affiliation\";s:5:\"value\";s:13:\"IIT Kharagpur\";}}s:12:\"head_tagline\";s:25:\"— MESSAGE FROM THE HEAD\";s:10:\"head_title\";s:56:\"Welcome to the <em>G.S. Sanyal School of Technology</em>\";s:12:\"head_message\";s:368:\"The G.S. Sanyal School of Technology at IIT Kharagpur was established with a singular purpose: to pursue rigorous, impactful research while nurturing the next generation of engineers and scientists who will shape the future.\r\n\r\nWhether you are a prospective student, a research collaborator, or a partner from industry, I invite you to explore what GSSST has to offer.\";s:9:\"head_name\";s:16:\"Prof. Goutam Das\";s:9:\"head_role\";s:50:\"Professor & Head, G.S. Sanyal School of Technology\";s:10:\"head_email\";s:23:\"gdas@gssst.iitkgp.ac.in\";s:14:\"head_photo_url\";s:68:\"http://localhost:8000/wp-content/uploads/2026/09/faculty-ec-gdas.jpg\";}','auto');
